import{_ as t,g as a,e as r,a4 as n}from"./chunks/framework.CEYJDsBW.js";const f=JSON.parse('{"title":"TeslaStrikeEvent","description":"","frontmatter":{},"headers":[],"relativePath":"en/anvilcraft/26.1/events/tesla-strike-event.md","filePath":"en/anvilcraft/26.1/events/tesla-strike-event.md"}'),i={name:"en/anvilcraft/26.1/events/tesla-strike-event.md"};function c(o,e,s,l,d,h){return a(),r("div",null,[...e[0]||(e[0]=[n('<h1 id="teslastrikeevent" tabindex="-1">TeslaStrikeEvent <a class="header-anchor" href="#teslastrikeevent" aria-label="Permalink to &quot;TeslaStrikeEvent&quot;">​</a></h1><p>When adding protection rules to Tesla towers, inspect <code>TargetEntity.getTarget()</code> or <code>TargetBlock.getTargetPos()</code> first. <code>getEntity()</code> is inherited from the block entity event and returns the tower initiating the discharge. Entity targets have already passed range and filter checks and the tower is about to decide whether to strike; canceling the first target clears it and ends this selection.</p><p>Subsequent jumps in a chain attack also post <code>TargetEntity</code>; canceling a jump stops only the remaining chain while preserving earlier hits. Only when no candidate entity exists does it look for a lightning rod and post <code>TargetBlock</code>; canceling clears that target and syncs state. The target state is the block state read when the event was constructed. <a href="https://github.com/Anvil-Dev/AnvilCraft/blob/7ac05a76988c98454c0384513fcab44d9da4cf88/src/main/java/dev/dubhe/anvilcraft/block/entity/TeslaTowerBlockEntity.java" target="_blank" rel="noreferrer">Target selection &amp; chain progression</a></p><table tabindex="0"><thead><tr><th>Event Type</th><th>Construction Site</th></tr></thead><tbody><tr><td><code>TeslaStrikeEvent</code></td><td>No direct construction call site under this name in this commit</td></tr><tr><td><code>TeslaStrikeEvent.TargetEntity</code></td><td><a href="https://github.com/Anvil-Dev/AnvilCraft/blob/7ac05a76988c98454c0384513fcab44d9da4cf88/src/main/java/dev/dubhe/anvilcraft/block/entity/TeslaTowerBlockEntity.java#L278" target="_blank" rel="noreferrer"><code>TeslaTowerBlockEntity:278</code></a>, <a href="https://github.com/Anvil-Dev/AnvilCraft/blob/7ac05a76988c98454c0384513fcab44d9da4cf88/src/main/java/dev/dubhe/anvilcraft/block/entity/TeslaTowerBlockEntity.java#L326" target="_blank" rel="noreferrer"><code>TeslaTowerBlockEntity:326</code></a></td></tr><tr><td><code>TeslaStrikeEvent.TargetBlock</code></td><td><a href="https://github.com/Anvil-Dev/AnvilCraft/blob/7ac05a76988c98454c0384513fcab44d9da4cf88/src/main/java/dev/dubhe/anvilcraft/block/entity/TeslaTowerBlockEntity.java#L304" target="_blank" rel="noreferrer"><code>TeslaTowerBlockEntity:304</code></a></td></tr></tbody></table>',4)])])}const b=t(i,[["render",c]]);export{f as __pageData,b as default};
